        const mask = context.createRadialGradient(size / 2, size / 2, size * .18, size / 2, size / 2, size * .5);
        mask.addColorStop(0, 'rgba(0,0,0,0)');
        mask.addColorStop(1, 'rgba(0,0,0,1)');
