      world.setActivePlanet('moon');
      world.setActiveLayer('surface');
      this.player = new PlayerState();
      this.ball = new BallState(this.player);
      this.time = 0;
      this.score = 0;
      this.style = 0;
      this.styleHold = 0;
      this.stage = 0;
      this.objectiveKey = '';
      this.charge = 0;
      this.charging = false;
      this.queuedKick = null;
      this.queuedSpin = null;
      this.snapHeld = false;
      this.snapBuffer = 0;
      this.lineHeld = false;
      this.lineActive = false;
      this.lineHoldTime = 0;
      this.kickVisual = 0;
      this.shake = 0;
      this.cameraRoll = 0;
      this.cameraYawVelocity = 0;
      this.cameraPitchVelocity = 0;
      this.lastYaw = 0;
      this.hitStop = 0;
      this.rewardFlash = 0;
      this.lastTrick = null;
      this.cores.clear();
      this.drops = 0;
      this.won = false;
      this.paused = false;
      this.started = wasStarted;
      this.respawnCount = 0;
      this.transition = { active: false, from: 'surface', to: 'surface', count: 0, lastReason: 'restart', timer: 0 };
