          setVspeed(this.player.velocity, this.player.up, Math.max(vspeedOf(this.player.velocity, this.player.up), 11.2));
          this.player.jumpsUsed = 0;
          ball.anchor = null;
          ball.mode = 'returning';
          ball.returnTime = 0;
