      ball.position.copy(anchor.position);
      this.pitonCooldown = GRAPPLE_PROFILE.cooldown;
      this.grappleReel = Math.max(this.grappleReel, GRAPPLE_PROFILE.reelGrace);
      this.lineActive = true;
