      input.moveStick.down(fakeTouch(101, 80, 520, 0));
      input.lookStick.down(fakeTouch(202, 250, 400, 0));
      input.moveStick.move(fakeTouch(101, 80, 466, 80));
      input.lookStick.move(fakeTouch(202, 314, 400, 80));
